def transform(grid):
 h,w=len(grid),len(grid[0]);out=[row[:] for row in grid]
 pat=[[4,5,5],[8,5,8],[8,5,0]]
 seeds=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==1]
 for r,c in seeds:
  for dr in range(3):
   for dc in range(3):
    rr,cc=r+dr-1,c+dc-1
    if 0<=rr<h and 0<=cc<w: out[rr][cc]=pat[dr][dc]
 return out
